<?php
/** Lightweight accessible header when no companion design plugin is installed. */
defined('ABSPATH') || exit;
$options=frpmt_options();$logo=absint(frpmt_option('logo_id'));if(!$logo)$logo=absint(get_theme_mod('custom_logo'));
?><header class="frpmt-header frpmt-header-<?php echo esc_attr(frpmt_option('header_layout')?:'default'); ?>"><div class="frpmt-brand"><a href="<?php echo esc_url(home_url('/')); ?>" rel="home"><?php if($logo){echo wp_get_attachment_image($logo,'full',false,array('alt'=>get_bloginfo('name')));}else{echo esc_html(get_bloginfo('name'));} ?></a></div><button type="button" id="frpmt-menu-toggle" aria-controls="frpmt-menu" aria-expanded="false" hidden><?php esc_html_e('فهرست','frpmesh-hybrid'); ?></button><nav id="frpmt-menu" aria-label="<?php esc_attr_e('فهرست اصلی','frpmesh-hybrid'); ?>"><?php wp_nav_menu(array('theme_location'=>'primary','container'=>false,'fallback_cb'=>'wp_page_menu')); ?></nav><?php if(!empty($options['header_cta_text'])&&!empty($options['header_cta_url'])): ?><a href="<?php echo esc_url($options['header_cta_url']); ?>"><?php echo esc_html($options['header_cta_text']); ?></a><?php endif; ?><?php if(!empty($options['header_phone_text'])): ?><a href="tel:<?php echo esc_attr(preg_replace('/[^0-9+]/','',$options['header_phone_text'])); ?>"><?php echo esc_html($options['header_phone_text']); ?></a><?php endif; ?><?php if(!empty($options['header_cart'])&&function_exists('wc_get_cart_url')): ?><a href="<?php echo esc_url(wc_get_cart_url()); ?>"><?php esc_html_e('سبد خرید','frpmesh-hybrid'); ?></a><?php endif; ?></header>
